    def _validate_metar_json_structure(self, metar_data: Dict[str, Any]):
        """
        Helper method to validate METAR JSON structure
        
        Args:
            metar_data: Single METAR observation data
        """
        # Validate required fields existence
        assert "icaoId" in metar_data, "METAR must contain icaoId"
        assert "rawOb" in metar_data, "METAR must contain rawOb"
        
        # Validate field types
        if metar_data.get("temp") is not None:
            assert isinstance(metar_data["temp"], (int, float)), (
                "Temperature must be a number"
            )
        
        if metar_data.get("wspd") is not None:
            assert isinstance(metar_data["wspd"], int), (
                "Wind speed must be an integer"
            )
            assert metar_data["wspd"] >= 0, "Wind speed must be non-negative"
        
        if metar_data.get("wdir") is not None:
            # Can be integer or string (VRB)
            assert isinstance(metar_data["wdir"], (int, str)), (
                "Wind direction must be integer or string"
            )
            if isinstance(metar_data["wdir"], int):
                assert metar_data["wdir"] >= 0, (
                    "Wind direction must be non-negative"
                )
        
        if "clouds" in metar_data:
            assert isinstance(metar_data["clouds"], list), (
                "Clouds must be an array"
            )
            for cloud in metar_data["clouds"]:
                assert "cover" in cloud, "Cloud must have cover property"
                assert "base" in cloud, "Cloud must have base property"
                assert cloud["cover"] in [
                    "CLR", "CAVOK", "FEW", "SCT", "BKN", "OVC", "OVX"
                ], f"Invalid cloud cover: {cloud['cover']}"
        
        if metar_data.get("metarType") is not None:
            assert metar_data["metarType"] in [
                "METAR", "SPECI", "SYNOP", "BUOY", "CMAN"
            ], f"Invalid metarType: {metar_data['metarType']}"
